-- ══════════════════════════════════════════════════════════════════════
-- Plantilla GLOBAL: Acuerdo Pedagógico (formato DO-F-021), con la lista de
-- firmas de los estudiantes generada desde la matrícula del curso.
--
-- ── De dónde sale ─────────────────────────────────────────────────────
-- Del .docx institucional, convertido con el MISMO parser que ya usa el módulo
-- de informes para importar Word (`src/modules/reports/docx-import.ts`), así
-- que el encabezado, las tablas y los estilos son los del documento original y
-- no una reconstrucción a ojo.
--
-- ── Tres cosas que se cambiaron a propósito ───────────────────────────
-- 1) Los datos del curso pasaron a ser VARIABLES. El documento venía con
--    "Programación II / 341-C / 2026-1 / Julian Andrés Castaño" escritos
--    literalmente; una plantilla global con eso adentro le saldría igual a
--    todos los cursos de todas las instituciones.
-- 2) La FIRMA ESCANEADA del docente se retiró (eran 112 KB de PNG en base64 de
--    los 128 KB del cuerpo). Hornear la firma de una persona real en una
--    plantilla que cualquier institución puede usar no es aceptable, y además
--    era el 87% del peso del documento.
-- 3) El logo del encabezado pasó a `{{institucion.logo}}`, que sale de
--    `certificate_settings` — la misma fuente que ya usan los certificados y
--    los otros informes. Con el logo horneado, una institución habría impreso
--    el acuerdo con el membrete de otra.
--
-- ── Lo que el pedido pedía ────────────────────────────────────────────
-- El documento YA traía un "LISTADO DE ESTUDIANTES ASISTENTES AL ACUERDO", pero
-- con 22 filas VACÍAS numeradas a mano, para llenar con lapicera. Ahora es un
-- `{{#each estudiantes}}`: una fila por matriculado, con su número, nombre y
-- código, y la celda de Firma en blanco para firmar sobre el papel impreso.
-- El bloque de firmas de arriba (Docente / Vocero / Director) se mantiene tal
-- cual estaba en el formato.
--
-- Idempotente: si ya existe una global con este nombre, la actualiza.
-- ══════════════════════════════════════════════════════════════════════

DO $mig$
BEGIN
  IF to_regclass('public.report_templates') IS NULL THEN
    RAISE NOTICE 'report_templates ausente — se omite la plantilla del acuerdo';
    RETURN;
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.report_templates
     WHERE name = 'Acuerdo Pedagógico'
       AND owner_id IS NULL AND course_id IS NULL AND parent_id IS NULL
  ) THEN
    UPDATE public.report_templates SET
      description = 'Formato DO-F-021 con los datos del curso, el bloque de firmas y el listado de estudiantes generado desde la matrícula.',
      scope       = 'curso',
      body_html   = $acuerdo_b$<table style="border-collapse:collapse;width:100%;table-layout:fixed;"><tr><td style="padding:4px 6px;vertical-align:middle;width:9.6%;border:1px solid #444;"><p style="text-align:justify"><span style="font-size:9pt">Programa Académico</span></p></td><td colspan="3" style="padding:4px 6px;vertical-align:middle;width:40.3%;border:1px solid #444;"><p style="text-align:justify"><span style="font-size:9pt">{{curso.programa}}</span></p></td></tr><tr><td style="padding:4px 6px;vertical-align:middle;width:9.6%;border:1px solid #444;"><p style="text-align:justify"><span style="font-size:9pt">Nombre Del Curso</span></p></td><td colspan="3" style="padding:4px 6px;vertical-align:middle;width:40.3%;border:1px solid #444;"><p style="text-align:justify"><span style="font-size:9pt">{{curso.nombre}}</span></p></td></tr><tr><td style="padding:4px 6px;vertical-align:middle;width:9.6%;border:1px solid #444;"><p style="text-align:justify"><span style="font-size:9pt">Grupo</span></p></td><td style="padding:4px 6px;vertical-align:middle;width:16.1%;border:1px solid #444;"><p style="text-align:justify"><span style="font-size:9pt">{{curso.grupo}}</span></p></td><td style="padding:4px 6px;vertical-align:middle;width:5.6%;border:1px solid #444;"><p style="text-align:justify"><span style="font-size:9pt">Semestre</span></p></td><td style="padding:4px 6px;vertical-align:middle;width:18.6%;border:1px solid #444;"><p style="text-align:justify"><span style="font-size:9pt">{{curso.semestre}}</span></p></td></tr><tr><td style="padding:4px 6px;vertical-align:middle;width:9.6%;border:1px solid #444;"><p style="text-align:justify"><span style="font-size:9pt">Periodo</span></p></td><td style="padding:4px 6px;vertical-align:middle;width:16.1%;border:1px solid #444;"><p style="text-align:justify"><span style="font-size:9pt">{{periodo}}</span></p></td><td style="padding:4px 6px;vertical-align:middle;width:5.6%;border:1px solid #444;"><p style="text-align:justify"><span style="font-size:9pt">Fecha</span></p></td><td style="padding:4px 6px;vertical-align:middle;width:18.6%;border:1px solid #444;">&nbsp;</td></tr><tr><td style="padding:4px 6px;vertical-align:middle;width:9.6%;border:1px solid #444;"><p style="text-align:justify"><span style="font-size:9pt">Profesor</span></p></td><td colspan="3" style="padding:4px 6px;vertical-align:middle;width:40.3%;border:1px solid #444;"><p style="text-align:justify"><span style="font-size:9pt">{{docente.nombre}}</span></p></td></tr></table>
