<table style="border-collapse:collapse;width:100%;table-layout:fixed;"><tr><td style="padding:4px 6px;vertical-align:top;width:50%;border:1px solid #444;"><p style="text-align:justify"><span style="font-size:9pt">Acuerdo sobre los aspectos metodológicos</span></p><p style="text-align:justify"><span style="font-size:9pt">Describa acá la modalidad de las clases, la metodología acordada y la dinámica de cada sesión.</p></td></tr><tr><td style="padding:4px 6px;vertical-align:top;width:50%;border:1px solid #444;"><p style="text-align:justify"><span style="font-size:9pt">Acuerdo sobre los aspectos de evaluación</span></p><p style="text-align:justify"><span style="font-size:9pt">La nota final se compone de los siguientes cortes:</span></p><table style="border-collapse:collapse;width:100%;margin-top:6px;table-layout:fixed;"><tr><td style="padding:3px 5px;border:1px solid #444;width:26%;background-color:#d9d9d9;"><span style="font-size:9pt"><strong>Corte</strong></span></td><td style="padding:3px 5px;border:1px solid #444;width:12%;background-color:#d9d9d9;"><span style="font-size:9pt"><strong>Peso</strong></span></td><td style="padding:3px 5px;border:1px solid #444;width:32%;background-color:#d9d9d9;"><span style="font-size:9pt"><strong>Fechas</strong></span></td><td style="padding:3px 5px;border:1px solid #444;width:30%;background-color:#d9d9d9;"><span style="font-size:9pt"><strong>Distribución</strong></span></td></tr>{{#each cortes_curso}}<tr><td style="padding:3px 5px;border:1px solid #444;"><span style="font-size:9pt">{{nombre}}</span></td><td style="padding:3px 5px;border:1px solid #444;"><span style="font-size:9pt">{{peso}}%</span></td><td style="padding:3px 5px;border:1px solid #444;"><span style="font-size:9pt">{{inicio}} a {{fin}}</span></td><td style="padding:3px 5px;border:1px solid #444;"><span style="font-size:9pt">Exámenes {{peso_examenes}}% · Talleres {{peso_talleres}}% · Proyectos {{peso_proyectos}}% · Asistencia {{peso_asistencia}}%</span></td></tr>{{/each